/** Only source-supported keys render; missing keys deliberately produce no glyph. */
export function CodexCuIcon({ name, size, label, alignment, idPrefix, ...props }) {
  const reactId = React.useId();
  const sourceKey = aliases[name] ?? name;
  const definition = iconDefinitions[sourceKey];
  if (!definition) return null;
  const accessibleLabel = props['aria-label'] ?? label;
  const hasLabel = Boolean(accessibleLabel || props['aria-labelledby']);
  const rendered = alignedBody(definition, authoredPaint(definition), alignment);
  const prefix = idPrefix ?? definition.name + '-' + reactId;
  const style = { ...rendered.style, ...(definition.wrapper ? { flexShrink: 0 } : {}), ...definition.style, ...(name === 'forward' ? { transform: 'scaleX(-1)' } : {}), ...props.style };
  return <svg
    {...definition.attributes}
    xmlns="http://www.w3.org/2000/svg"
    width={size ?? definition.width}
    height={size ?? definition.height}
    viewBox={definition.viewBox}
    aria-hidden={props['aria-hidden'] ?? (hasLabel ? undefined : true)}
    role={props.role ?? (hasLabel ? 'img' : undefined)}
    focusable={definition.wrapper ? 'false' : undefined}
    data-icon-p3={rendered.supportsWideGamut ? definition.name : undefined}
    {...props}
    aria-label={accessibleLabel}
    style={style}
    dangerouslySetInnerHTML={{ __html: prefixedBody(rendered.body, prefix) }}
  />;
}

/** Qki keys, with the exact NOi Office size/paint branch selection. */
export function CodexCuFileIcon({ type = 'file', size, variant = 'branded', style, ...props }) {
  const office = type === 'artifactDocument' || type === 'spreadsheet' || type === 'presentation';
  let key = 'file:' + type;
  let officeColor;
  if (office && size === 16) {
    key += ':16';
    if (variant === 'branded') officeColor = 'var(--color-file-' + ({ artifactDocument: 'document', spreadsheet: 'spreadsheet', presentation: 'presentation' })[type] + ')';
  } else if (office && size === 20 && variant === 'monochrome') key += ':20-monochrome';
  return <CodexCuIcon name={key} size={size} {...props} style={{ ...(officeColor ? { color: officeColor } : {}), ...style }} />;
}
